arguments.file_text:
@page "/settings"
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul class="settings-nav">
            @foreach (var section in _sections)
            {
                <li class="@(ActiveSection == section.Key ? "active" : "")" @onclick="() => ActiveSection = section.Key">
                    <span class="nav-icon">@section.Icon</span>
                    <span class="nav-label">@section.Label</span>
                </li>
            }
        </ul>
    </nav>

    <main class="settings-content">
        @if (_loading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfileSection()
                    break;
                case "notifications":
                    @RenderNotificationsSection()
                    break;
                case "security":
                    @RenderSecuritySection()
                    break;
                case "appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }
    </main>
</div>

@if (!string.IsNullOrEmpty(_toastMessage))
{
    <div class="toast @(_toastType)">
        <span>@_toastMessage</span>
        <button class="toast-close" @onclick="DismissToast">&times;</button>
    </div>
}

@if (_showRevokeConfirmation)
{
    <div class="modal-overlay" @onclick="CancelRevoke">
        <div class="modal-dialog" @onclick:stopPropagation="true">
            <h3>Revoke Session</h3>
            <p>Are you sure you want to revoke this session? The device will be signed out immediately.</p>
            <div class="modal-actions">
                <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke</button>
            </div>
        </div>
    </div>
}

@code {
    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;

    // Toast
    private string _toastMessage = "";
    private string _toastType = "";

    // Profile
    private UserProfile? _profile;
    private UserProfile? _savedProfile;
    private string _editDisplayName = "";
    private string _editEmail = "";
    private string _editBio = "";
    private string _editAvatarUrl = "";

    // Notifications
    private NotificationPrefs? _notificationPrefs;

    // Security
    private SecuritySettings? _securitySettings;
    private bool _changePasswordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _showRevokeConfirmation;
    private string? _sessionToRevoke;

    // Appearance
    private AppearanceSettings? _appearanceSettings;

    private record SectionInfo(string Key, string Label, string Icon);

    private readonly SectionInfo[] _sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨")
    ];

    protected override async Task OnInitializedAsync()
    {
        await LoadAllData();
        _loading = false;
    }

    private async Task LoadAllData()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        _profile = profileTask.Result;
        _savedProfile = _profile;
        SetProfileFields(_profile);

        _notificationPrefs = notifTask.Result;
        _securitySettings = securityTask.Result;
        _appearanceSettings = appearanceTask.Result;
    }

    private void SetProfileFields(UserProfile profile)
    {
        _editDisplayName = profile.DisplayName;
        _editEmail = profile.Email;
        _editBio = profile.Bio;
        _editAvatarUrl = profile.AvatarUrl;
    }

    // --- Profile ---

    private async Task SaveProfile()
    {
        var updated = new UserProfile(_editDisplayName, _editEmail, _editAvatarUrl, _editBio);
        await SettingsService.SaveProfileAsync(updated);
        _savedProfile = updated;
        _profile = updated;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            SetProfileFields(_savedProfile);
        }
    }

    // --- Notifications ---

    private void ToggleEmailNotifications(ChangeEventArgs e)
    {
        if (_notificationPrefs is not null)
            _notificationPrefs = _notificationPrefs with { EmailNotifications = (bool)(e.Value ?? false) };
    }

    private void TogglePushNotifications(ChangeEventArgs e)
    {
        if (_notificationPrefs is not null)
            _notificationPrefs = _notificationPrefs with { PushNotifications = (bool)(e.Value ?? false) };
    }

    private void ToggleWeeklyDigest(ChangeEventArgs e)
    {
        if (_notificationPrefs is not null)
            _notificationPrefs = _notificationPrefs with { WeeklyDigest = (bool)(e.Value ?? false) };
    }

    private void ToggleChannelMute(string channel, ChangeEventArgs e)
    {
        if (_notificationPrefs is null) return;
        var muted = new List<string>(_notificationPrefs.MutedChannels);
        bool isMuted = (bool)(e.Value ?? false);
        if (isMuted && !muted.Contains(channel))
            muted.Add(channel);
        else if (!isMuted)
            muted.Remove(channel);
        _notificationPrefs = _notificationPrefs with { MutedChannels = muted };
    }

    private async Task SaveNotifications()
    {
        if (_notificationPrefs is not null)
        {
            await SettingsService.SaveNotificationPrefsAsync(_notificationPrefs);
            ShowToast("Notification preferences saved!", "success");
        }
    }

    // --- Security ---

    private async Task ChangePassword()
    {
        if (_newPassword != _confirmPassword)
        {
            ShowToast("Passwords do not match.", "error");
            return;
        }
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _changePasswordExpanded = false;
        ShowToast("Password updated successfully!", "success");
    }

    private void RequestRevoke(string sessionId)
    {
        _sessionToRevoke = sessionId;
        _showRevokeConfirmation = true;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
        _showRevokeConfirmation = false;
    }

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            ShowToast("Session revoked.", "success");
        }
        _showRevokeConfirmation = false;
        _sessionToRevoke = null;
    }

    // --- Appearance ---

    private void SetTheme(string theme)
    {
        if (_appearanceSettings is not null)
            _appearanceSettings = _appearanceSettings with { Theme = theme };
    }

    private void SetFontSize(string size)
    {
        if (_appearanceSettings is not null)
            _appearanceSettings = _appearanceSettings with { FontSize = size };
    }

    private void SetLanguage(ChangeEventArgs e)
    {
        if (_appearanceSettings is not null)
            _appearanceSettings = _appearanceSettings with { Language = e.Value?.ToString() ?? "en" };
    }

    private void ToggleCompactMode(ChangeEventArgs e)
    {
        if (_appearanceSettings is not null)
            _appearanceSettings = _appearanceSettings with { CompactMode = (bool)(e.Value ?? false) };
    }

    private async Task SaveAppearance()
    {
        if (_appearanceSettings is not null)
        {
            await SettingsService.SaveAppearanceAsync(_appearanceSettings);
            ShowToast("Appearance settings saved!", "success");
        }
    }

    // --- Toast ---

    private void ShowToast(string message, string type)
    {
        _toastMessage = message;
        _toastType = type;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        _toastMessage = "";
        await InvokeAsync(StateHasChanged);
    }

    private void DismissToast()
    {
        _toastMessage = "";
    }

    // --- Render Fragments ---

    private RenderFragment RenderProfileSection() => __builder =>
    {
        <h2>Profile Settings</h2>
        <div class="settings-section">
            <div class="avatar-section">
                <div class="avatar-preview">
                    @if (!string.IsNullOrWhiteSpace(_editAvatarUrl))
                    {
                        <img src="@_editAvatarUrl" alt="Avatar" />
                    }
                    else
                    {
                        <div class="avatar-placeholder">No Avatar</div>
                    }
                </div>
                <div class="avatar-url">
                    <label>Avatar URL</label>
                    <input type="url" @bind="_editAvatarUrl" placeholder="https://example.com/avatar.png" />
                </div>
            </div>

            <div class="form-group">
                <label>Display Name</label>
                <input type="text" @bind="_editDisplayName" />
            </div>

            <div class="form-group">
                <label>Email</label>
                <input type="email" @bind="_editEmail" />
            </div>

            <div class="form-group">
                <label>Bio</label>
                <textarea rows="4" @bind="_editBio"></textarea>
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </div>
    };

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <h2>Notification Preferences</h2>
        <div class="settings-section">
            @if (_notificationPrefs is not null)
            {
                <div class="toggle-group">
                    <label class="toggle-item">
                        <input type="checkbox" checked="@_notificationPrefs.EmailNotifications"
                               @onchange="ToggleEmailNotifications" />
                        <span class="toggle-switch"></span>
                        <span>Email Notifications</span>
                    </label>

                    <label class="toggle-item">
                        <input type="checkbox" checked="@_notificationPrefs.PushNotifications"
                               @onchange="TogglePushNotifications" />
                        <span class="toggle-switch"></span>
                        <span>Push Notifications</span>
                    </label>

                    <label class="toggle-item">
                        <input type="checkbox" checked="@_notificationPrefs.WeeklyDigest"
                               @onchange="ToggleWeeklyDigest" />
                        <span class="toggle-switch"></span>
                        <span>Weekly Digest</span>
                    </label>
                </div>

                <h3>Muted Channels</h3>
                <div class="channel-list">
                    @if (_notificationPrefs.MutedChannels.Count == 0)
                    {
                        <p class="text-muted">No channels configured.</p>
                    }
                    else
                    {
                        @foreach (var channel in _notificationPrefs.MutedChannels)
                        {
                            <label class="channel-item">
                                <input type="checkbox" checked="@true"
                                       @onchange="(e) => ToggleChannelMute(channel, e)" />
                                <span>@channel</span>
                            </label>
                        }
                    }
                </div>

                <div class="button-group">
                    <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                </div>
            }
        </div>
    };

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <h2>Security Settings</h2>
        <div class="settings-section">
            @if (_securitySettings is not null)
            {
                <div class="expandable-panel">
                    <button class="panel-header" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                        <span>Change Password</span>
                        <span class="expand-icon">@(_changePasswordExpanded ? "▼" : "▶")</span>
                    </button>
                    @if (_changePasswordExpanded)
                    {
                        <div class="panel-body">
                            <div class="form-group">
                                <label>Current Password</label>
                                <input type="password" @bind="_currentPassword" />
                            </div>
                            <div class="form-group">
                                <label>New Password</label>
                                <input type="password" @bind="_newPassword" />
                            </div>
                            <div class="form-group">
                                <label>Confirm Password</label>
                                <input type="password" @bind="_confirmPassword" />
                            </div>
                            <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>
                        </div>
                    }
                </div>

                <div class="security-item">
                    <div class="tfa-status">
                        <span>Two-Factor Authentication</span>
                        <span class="status-badge @(_securitySettings.TwoFactorEnabled ? "enabled" : "disabled")">
                            @(_securitySettings.TwoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </div>
                </div>

                @if (_securitySettings.LastPasswordChange.HasValue)
                {
                    <p class="text-muted">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                }

                <h3>Active Sessions</h3>
                <div class="sessions-table-wrapper">
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
