        _editDisplayName = profile.DisplayName;
        _editEmail = profile.Email;
        _editBio = profile.Bio;
        _editAvatarUrl = profile.AvatarUrl;
    }

    // --- Profile ---

    private async Task SaveProfile()
    {
        var updated = new UserProfile(_editDisplayName, _editEmail, _editAvatarUrl, _editBio);
        await SettingsService.SaveProfileAsync(updated);
        _savedProfile = updated;
        _profile = updated;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            SetProfileFields(_savedProfile);
        }
    }

    // --- Notifications ---

    private void ToggleEmailNotifications(ChangeEventArgs e)
    {
        if (_notificationPrefs is not null)
            _notificationPrefs = _notificationPrefs with { EmailNotifications = (bool)(e.Value ?? false) };
    }

    private void TogglePushNotifications(ChangeEventArgs e)
    {
        if (_notificationPrefs is not null)
            _notificationPrefs = _notificationPrefs with { PushNotifications = (bool)(e.Value ?? false) };
    }

    private void ToggleWeeklyDigest(ChangeEventArgs e)
    {
        if (_notificationPrefs is not null)
            _notificationPrefs = _notificationPrefs with { WeeklyDigest = (bool)(e.Value ?? false) };
    }

    private void ToggleChannelMute(string channel, ChangeEventArgs e)
    {
        if (_notificationPrefs is null) return;
        var muted = new List<string>(_notificationPrefs.MutedChannels);
        bool isMuted = (bool)(e.Value ?? false);
        if (isMuted && !muted.Contains(channel))
            muted.Add(channel);
        else if (!isMuted)
            muted.Remove(channel);
        _notificationPrefs = _notificationPrefs with { MutedChannels = muted };
    }

    private async Task SaveNotifications()
    {
        if (_notificationPrefs is not null)
        {
            await SettingsService.SaveNotificationPrefsAsync(_notificationPrefs);
            ShowToast("Notification preferences saved!", "success");
        }
    }

    // --- Security ---

    private async Task ChangePassword()
    {
        if (_newPassword != _confirmPassword)
        {
            ShowToast("Passwords do not match.", "error");
            return;
        }
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _changePasswordExpanded = false;
        ShowToast("Password updated successfully!", "success");
    }

    private void RequestRevoke(string sessionId)
    {
        _sessionToRevoke = sessionId;
        _showRevokeConfirmation = true;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
        _showRevokeConfirmation = false;
    }

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            ShowToast("Session revoked.", "success");
        }
        _showRevokeConfirmation = false;
        _sessionToRevoke = null;
    }

    // --- Appearance ---

    private void SetTheme(string theme)
    {
        if (_appearanceSettings is not null)
            _appearanceSettings = _appearanceSettings with { Theme = theme };
    }

    private void SetFontSize(string size)
    {
        if (_appearanceSettings is not null)
            _appearanceSettings = _appearanceSettings with { FontSize = size };
    }

    private void SetLanguage(ChangeEventArgs e)
    {
        if (_appearanceSettings is not null)
            _appearanceSettings = _appearanceSettings with { Language = e.Value?.ToString() ?? "en" };
    }

    private void ToggleCompactMode(ChangeEventArgs e)
    {
        if (_appearanceSettings is not null)
            _appearanceSettings = _appearanceSettings with { CompactMode = (bool)(e.Value ?? false) };
    }

    private async Task SaveAppearance()
    {
        if (_appearanceSettings is not null)
        {
            await SettingsService.SaveAppearanceAsync(_appearanceSettings);
            ShowToast("Appearance settings saved!", "success");
        }
    }

    // --- Toast ---

    private void ShowToast(string message, string type)
    {
        _toastMessage = message;
        _toastType = type;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        _toastMessage = "";
        await InvokeAsync(StateHasChanged);
    }

    private void DismissToast()
    {
        _toastMessage = "";
    }

    // --- Render Fragments ---

    private RenderFragment RenderProfileSection() => __builder =>
    {
        <h2>Profile Settings</h2>
        <div class="settings-section">
            <div class="avatar-section">
                <div class="avatar-preview">
                    @if (!string.IsNullOrWhiteSpace(_editAvatarUrl))
                    {
                        <img src="@_editAvatarUrl" alt="Avatar" />
                    }
                    else
                    {
                        <div class="avatar-placeholder">No Avatar</div>
                    }
                </div>
                <div class="avatar-url">
                    <label>Avatar URL</label>
                    <input type="url" @bind="_editAvatarUrl" placeholder="https://example.com/avatar.png" />
