    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <h2>Notification Preferences</h2>
        <div class="settings-section">
            @if (_notificationPrefs is not null)
            {
                <div class="toggle-group">
                    <label class="toggle-item">
                        <input type="checkbox" checked="@_notificationPrefs.EmailNotifications"
                               @onchange="ToggleEmailNotifications" />
                        <span class="toggle-switch"></span>
                        <span>Email Notifications</span>
                    </label>

                    <label class="toggle-item">
                        <input type="checkbox" checked="@_notificationPrefs.PushNotifications"
                               @onchange="TogglePushNotifications" />
                        <span class="toggle-switch"></span>
                        <span>Push Notifications</span>
                    </label>

                    <label class="toggle-item">
                        <input type="checkbox" checked="@_notificationPrefs.WeeklyDigest"
                               @onchange="ToggleWeeklyDigest" />
                        <span class="toggle-switch"></span>
                        <span>Weekly Digest</span>
                    </label>
                </div>

                <h3>Muted Channels</h3>
                <div class="channel-list">
                    @if (_notificationPrefs.MutedChannels.Count == 0)
                    {
                        <p class="text-muted">No channels configured.</p>
                    }
                    else
                    {
                        @foreach (var channel in _notificationPrefs.MutedChannels)
                        {
                            <label class="channel-item">
                                <input type="checkbox" checked="@true"
                                       @onchange="(e) => ToggleChannelMute(channel, e)" />
