    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <h2>Security Settings</h2>
        <div class="settings-section">
            @if (_securitySettings is not null)
            {
                <div class="expandable-panel">
                    <button class="panel-header" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                        <span>Change Password</span>
                        <span class="expand-icon">@(_changePasswordExpanded ? "▼" : "▶")</span>
                    </button>
                    @if (_changePasswordExpanded)
                    {
                        <div class="panel-body">
                            <div class="form-group">
                                <label>Current Password</label>
                                <input type="password" @bind="_currentPassword" />
                            </div>
                            <div class="form-group">
                                <label>New Password</label>
                                <input type="password" @bind="_newPassword" />
                            </div>
                            <div class="form-group">
                                <label>Confirm Password</label>
                                <input type="password" @bind="_confirmPassword" />
                            </div>
                            <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>
                        </div>
                    }
                </div>

                <div class="security-item">
                    <div class="tfa-status">
                        <span>Two-Factor Authentication</span>
                        <span class="status-badge @(_securitySettings.TwoFactorEnabled ? "enabled" : "disabled")">
                            @(_securitySettings.TwoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </div>
                </div>

                @if (_securitySettings.LastPasswordChange.HasValue)
                {
                    <p class="text-muted">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                }

                <h3>Active Sessions</h3>
                <div class="sessions-table-wrapper">
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@session.LastActive.ToString("g")</td>
                                    <td>
                                        @if (session != _securitySettings.Sessions.FirstOrDefault())
                                        {
                                            <button class="btn btn-danger btn-sm" @onclick="() => RequestRevoke(session.Id)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="text-muted">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
        </div>
    };

    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <h2>Appearance Settings</h2>
        <div class="settings-section">
            @if (_appearanceSettings is not null)
            {
                <div class="form-group">
                    <label>Theme</label>
                    <div class="radio-group">
                        <label class="radio-item">
                            <input type="radio" name="theme" value="Light"
                                   checked="@(_appearanceSettings.Theme == "Light")"
                                   @onchange="() => SetTheme("Light")" />
                            <span>Light</span>
                        </label>
                        <label class="radio-item">
                            <input type="radio" name="theme" value="Dark"
                                   checked="@(_appearanceSettings.Theme == "Dark")"
                                   @onchange="() => SetTheme("Dark")" />
                            <span>Dark</span>
                        </label>
                        <label class="radio-item">
                            <input type="radio" name="theme" value="System"
                                   checked="@(_appearanceSettings.Theme == "System")"
                                   @onchange="() => SetTheme("System")" />
                            <span>System</span>
                        </label>
                    </div>
                </div>

                <div class="form-group">
                    <label>Font Size</label>
                    <div class="radio-group">
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="Small"
                                   checked="@(_appearanceSettings.FontSize == "Small")"
                                   @onchange="() => SetFontSize("Small")" />
                            <span>Small</span>
                        </label>
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="Medium"
                                   checked="@(_appearanceSettings.FontSize == "Medium")"
                                   @onchange="() => SetFontSize("Medium")" />
                            <span>Medium</span>
                        </label>
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="Large"
                                   checked="@(_appearanceSettings.FontSize == "Large")"
                                   @onchange="() => SetFontSize("Large")" />
                            <span>Large</span>
                        </label>
                    </div>
                </div>

                <div class="form-group">
                    <label>Language</label>
                    <select @onchange="SetLanguage" value="@_appearanceSettings.Language">
                        <option value="en">English</option>
                        <option value="es">Spanish</option>
                        <option value="fr">French</option>
                        <option value="de">German</option>
                        <option value="ja">Japanese</option>
                        <option value="zh">Chinese</option>
                    </select>
                </div>

                <label class="toggle-item">
                    <input type="checkbox" checked="@_appearanceSettings.CompactMode"
                           @onchange="ToggleCompactMode" />
                    <span class="toggle-switch"></span>
                    <span>Compact Mode</span>
                </label>

                <div class="preview-area">
                    <h4>Live Preview</h4>
                    <div class="preview-box @(_appearanceSettings.Theme.ToLower()) @(_appearanceSettings.CompactMode ? "compact" : "")"
                         style="font-size: @GetPreviewFontSize()">
                        <div class="preview-header">Sample Header</div>
                        <p class="preview-text">This is how your content will look with the selected settings.</p>
                        <button class="preview-button">Sample Button</button>
                    </div>
                </div>

                <div class="button-group">
                    <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
                </div>
            }
        </div>
    };

    private string GetPreviewFontSize() => _appearanceSettings?.FontSize switch
    {
        "Small" => "12px",
        "Large" => "18px",
        _ => "14px"
    };
}
"}

