@page "/settings"
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul class="settings-nav">
            @foreach (var section in _sections)
            {
                <li class="@(ActiveSection == section.Key ? "active" : "")" @onclick="() => ActiveSection = section.Key">
                    <span class="nav-icon">@section.Icon</span>
                    <span class="nav-label">@section.Label</span>
                </li>
            }
        </ul>
    </nav>

    <main class="settings-content">
        @if (_loading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfileSection()
                    break;
                case "notifications":
                    @RenderNotificationsSection()
                    break;
                case "security":
                    @RenderSecuritySection()
                    break;
                case "appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }
    </main>
</div>

@if (!string.IsNullOrEmpty(_toastMessage))
{
    <div class="toast @(_toastType)">
        <span>@_toastMessage</span>
        <button class="toast-close" @onclick="DismissToast">&times;</button>
    </div>
}

@if (_showRevokeConfirmation)
{
    <div class="modal-overlay" @onclick="CancelRevoke">
        <div class="modal-dialog" @onclick:stopPropagation="true">
            <h3>Revoke Session</h3>
            <p>Are you sure you want to revoke this session? The device will be signed out immediately.</p>
            <div class="modal-actions">
                <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke</button>
            </div>
        </div>
    </div>
}

