+@page "/settings"
+@rendermode InteractiveServer
+@inject ISettingsService SettingsService
+
+<PageTitle>Settings</PageTitle>
+
+<div class="settings-container">
+    <nav class="settings-sidebar">
+        <ul class="settings-nav">
+            @foreach (var section in _sections)
+            {
+                <li class="@(ActiveSection == section.Key ? "active" : "")" @onclick="() => ActiveSection = section.Key">
+                    <span class="nav-icon">@section.Icon</span>
+                    <span class="nav-label">@section.Label</span>
+                </li>
+            }
+        </ul>
+    </nav>
+
+    <main class="settings-content">
+        @if (_loading)
+        {
+            <div class="loading-spinner">Loading...</div>
+        }
+        else
+        {
+            @switch (ActiveSection)
+            {
+                case "profile":
+                    @RenderProfileSection()
+                    break;
+                case "notifications":
+                    @RenderNotificationsSection()
+                    break;
+                case "security":
+                    @RenderSecuritySection()
+                    break;
+                case "appearance":
+                    @RenderAppearanceSection()
+                    break;
+            }
+        }
+    </main>
+</div>
+
+@if (!string.IsNullOrEmpty(_toastMessage))
+{
+    <div class="toast @(_toastType)">
+        <span>@_toastMessage</span>
+        <button class="toast-close" @onclick="DismissToast">&times;</button>
+    </div>
+}
+
+@if (_showRevokeConfirmation)
+{
+    <div class="modal-overlay" @onclick="CancelRevoke">
+        <div class="modal-dialog" @onclick:stopPropagation="true">
+            <h3>Revoke Session</h3>
+            <p>Are you sure you want to revoke this session? The device will be signed out immediately.</p>
+            <div class="modal-actions">
+                <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
+                <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke</button>
+            </div>
+        </div>
+    </div>
+}
+
+@code {
+    private string ActiveSection { get; set; } = "profile";
+    private bool _loading = true;
+
+    // Toast
+    private string _toastMessage = "";
+    private string _toastType = "";
+
+    // Profile
+    private UserProfile? _profile;
+    private UserProfile? _savedProfile;
+    private string _editDisplayName = "";
+    private string _editEmail = "";
+    private string _editBio = "";
+    private string _editAvatarUrl = "";
+
+    // Notifications
+    private NotificationPrefs? _notificationPrefs;
+
+    // Security
+    private SecuritySettings? _securitySettings;
+    private bool _changePasswordExpanded;
+    private string _currentPassword = "";
+    private string _newPassword = "";
+    private string _confirmPassword = "";
+    private bool _showRevokeConfirmation;
+    private string? _sessionToRevoke;
+
+    // Appearance
+    private AppearanceSettings? _appearanceSettings;
+
+    private record SectionInfo(string Key, string Label, string Icon);
+
+    private readonly SectionInfo[] _sections =
+    [
+        new("profile", "Profile", "👤"),
+        new("notifications", "Notifications", "🔔"),
+        new("security", "Security", "🔒"),
+        new("appearance", "Appearance", "🎨")
+    ];
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadAllData();
+        _loading = false;
+    }
+
+    private async Task LoadAllData()
+    {
+        var profileTask = SettingsService.GetProfileAsync();
+        var notifTask = SettingsService.GetNotificationPrefsAsync();
+        var securityTask = SettingsService.GetSecuritySettingsAsync();
+        var appearanceTask = SettingsService.GetAppearanceAsync();
+
+        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);
+
+        _profile = profileTask.Result;
+        _savedProfile = _profile;
+        SetProfileFields(_profile);
+
+        _notificationPrefs = notifTask.Result;
+        _securitySettings = securityTask.Result;
+        _appearanceSettings = appearanceTask.Result;
