+    }
+
+    private void ToggleChannelMute(string channel, ChangeEventArgs e)
+    {
+        if (_notificationPrefs is null) return;
+        var muted = new List<string>(_notificationPrefs.MutedChannels);
+        bool isMuted = (bool)(e.Value ?? false);
+        if (isMuted && !muted.Contains(channel))
+            muted.Add(channel);
+        else if (!isMuted)
+            muted.Remove(channel);
+        _notificationPrefs = _notificationPrefs with { MutedChannels = muted };
+    }
+
+    private async Task SaveNotifications()
+    {
+        if (_notificationPrefs is not null)
